-- [[ SECTION 1: SYSTEM DECODER ENGINE ]]
local _k1, _k2 = 29, 100
local _dec = function(t)
  local r = {}
  for i = 1, #t do
    local v = tonumber(t[i]:match("^(%d+)"))
    if v then
      local po = ((i - 1) % 7) + 2
      local orig = (v - _k2 - po) ~ _k1
      r[#r + 1] = string.char(orig)
    end
  end
  return table.concat(r)
end

